#!/usr/bin/env python3
# kmz2coords_toronto.py
import argparse, os, sys, zipfile, tempfile, base64
import xml.etree.ElementTree as ET
from typing import List
import pandas as pd
from pyproj import Transformer
from openpyxl import Workbook
from openpyxl.utils.dataframe import dataframe_to_rows

EMBED_GRID_NAME = "TO27CSv1.gsb"
EMBED_GRID_B64 = ""
NS = {"kml": "http://www.opengis.net/kml/2.2"}

def write_embedded_grid(tmp_dir: str) -> str:
    path = os.path.join(tmp_dir, EMBED_GRID_NAME)
    with open(path, "wb") as f:
        f.write(base64.b64decode(EMBED_GRID_B64.encode("ascii")))
    return path

def find_kml_in_kmz(kmz_path: str) -> str:
    extract_dir = os.path.join(tempfile.gettempdir(), os.path.splitext(os.path.basename(kmz_path))[0] + "_extract")
    if not os.path.isdir(extract_dir):
        os.makedirs(extract_dir, exist_ok=True)
        with zipfile.ZipFile(kmz_path, 'r') as z:
            z.extractall(extract_dir)
    for root, _, files in os.walk(extract_dir):
        for f in files:
            if f.lower().endswith(".kml"):
                return os.path.join(root, f)
    raise FileNotFoundError("No .kml found inside KMZ: " + kmz_path)

def parse_kml_to_rows(kml_path: str) -> List[dict]:
    tree = ET.parse(kml_path)
    root = tree.getroot()
    rows = []
    for pm in root.findall(".//kml:Placemark", NS):
        name_elem = pm.find("kml:name", NS)
        name = name_elem.text if name_elem is not None else "Unnamed"
        for coords_tag in pm.findall(".//kml:coordinates", NS):
            text = (coords_tag.text or "").strip()
            if not text:
                continue
            coords = text.split()
            for idx, c in enumerate(coords):
                parts = c.split(",")
                if len(parts) < 2:
                    continue
                try:
                    lon = float(parts[0]); lat = float(parts[1])
                except ValueError:
                    continue
                alt = None
                if len(parts) > 2 and parts[2] not in ("", "NaN", "nan"):
                    try:
                        alt = float(parts[2])
                    except ValueError:
                        alt = None
                rows.append({"feature_name": name,"vertex_index": idx+1,"lon_4269": lon,"lat_4269": lat,"elevation_m": alt})
    if not rows:
        raise RuntimeError("No <coordinates> found in: " + kml_path)
    return rows

def validate_geoset(df_geo):
    if df_geo.empty:
        raise RuntimeError("Parsed zero vertices from KML.")
    lat_ok = (df_geo["lat_4269"].between(42.0, 45.5)).all()
    lon_ok = (df_geo["lon_4269"].between(-81.5, -78.0)).all()
    if not (lat_ok and lon_ok):
        print("Warning: points outside typical GTA bounds; continuing.", file=sys.stderr)

def transform_to_nad27_utm17(df_geo, grid_path: str):
    pipeline = (
        f"+proj=pipeline "
        f"+step +proj=unitconvert +xy_in=deg +xy_out=rad "
        f"+step +inv +proj=hgridshift +grids={grid_path} "
        f"+step +proj=utm +zone=17 +datum=NAD27"
    )
    transformer = Transformer.from_pipeline(pipeline)
    E, N = transformer.transform(df_geo["lon_4269"].values, df_geo["lat_4269"].values)
    out = df_geo.copy()
    out["E_26717"] = E; out["N_26717"] = N
    if not (out["E_26717"].between(200000, 800000).all() and out["N_26717"].between(4700000, 5100000).all()):
        raise RuntimeError("UTM Zone 17N range check failed. Verify input CRS/grid.")
    return out

def write_xlsx(df, out_base: str, grid_used: str):
    df2 = df[["feature_name","vertex_index","lat_4269","lon_4269","N_26717","E_26717","elevation_m"]].copy()
    df2["lat_4269"] = df2["lat_4269"].round(6)
    df2["lon_4269"] = df2["lon_4269"].round(6)
    df2["N_26717"] = df2["N_26717"].round(3)
    df2["E_26717"] = df2["E_26717"].round(3)

    xlsx_path = out_base + "_Coordinates_Validated.xlsx"
    wb = Workbook(); ws = wb.active; ws.title = "Coordinates"
    ws.append(["", "","NAD 83 Geographic","NAD 83 Geographic",f"NAD 27 / UTM Zone 17N (Grid: {grid_used})",f"NAD 27 / UTM Zone 17N (Grid: {grid_used})",""])
    ws.append(["feature_name","vertex_index","lat_4269","lon_4269","N_26717","E_26717","elevation_m"])
    for r in dataframe_to_rows(df2, index=False, header=False):
        ws.append(r)
    wb.save(xlsx_path); return xlsx_path

def process_one(path: str, grid_used_label: str):
    if path.lower().endswith(".kmz"):
        kml_path = find_kml_in_kmz(path)
    elif path.lower().endswith(".kml"):
        kml_path = path
    else:
        raise ValueError("Unsupported input (use .kmz or .kml): " + path)
    rows = parse_kml_to_rows(kml_path)
    import pandas as pd
    df_geo = pd.DataFrame(rows).sort_values(["feature_name","vertex_index"])
    validate_geoset(df_geo)
    import tempfile
    tmp_dir = tempfile.mkdtemp(prefix="torgrid_")
    grid_file = write_embedded_grid(tmp_dir)
    df_out = transform_to_nad27_utm17(df_geo, grid_file)
    out_base = os.path.join(os.path.dirname(path), os.path.splitext(os.path.basename(path))[0])
    xlsx = write_xlsx(df_out, out_base, grid_used=grid_used_label)
    print("Wrote:", xlsx); return xlsx

def main():
    ap = argparse.ArgumentParser(description="KMZ/KML → NAD27/UTM17 (Toronto grid) XLSX exporter")
    ap.add_argument("--in", dest="inputs", nargs="+", required=True, help="KMZ/KML file(s)")
    args = ap.parse_args()
    for p in args.inputs:
        process_one(p, grid_used_label=EMBED_GRID_NAME)

if __name__ == "__main__":
    main()
